   mid=uuid.uuid4().hex;x={'id':mid,'channel_id':m.group(1),'author_id':u['id'],'author':userobj(u),'body':b['body'],'parent_id':b.get('parent_id'),'reply_count':0,'created_at':now(),'edited_at':None,'files':[],'reactions':[],'mentions':[]};S['messages'][mid]=x;save();return self.send(201,{'message':x})
  return self.send(404,{'error':'not found'})
 def do_PATCH(self): return self.send(404,{'error':'not found'})
